import { render } from '@solidjs/web';
import { createStore, createMemo, createEffect, For } from 'solid-js';

function Player(props) {
  let element;
  createEffect(
    () => props.index,
    (index, previous) => {
      if (previous === undefined || previous === index || !element?.isConnected)
        return;
      const animation = element.animate(
        [
          { transform: `translateY(${(previous - index) * 40}px)` },
          { transform: 'translateY(0)' },
        ],
        { duration: 250 },
      );
      return () => animation.cancel();
    },
  );
  return (
    <div ref={element} class="player">
      {props.player.name}: {props.player.score}
    </div>
  );
}
function App() {
  let newName, newScore;
  const [state, setState] = createStore({
    players: [
      { name: 'Mark', score: 3 },
      { name: 'Troy', score: 2 },
      { name: 'Jenny', score: 1 },
      { name: 'David', score: 8 },
    ],
  });
  const sorted = createMemo(() =>
    [...state.players].sort(
      (a, b) => b.score - a.score || a.name.localeCompare(b.name),
    ),
  );
  return (
    <>
      <h1>Scoreboard</h1>
      <For each={sorted()}>
        {(player, index) => <Player player={player} index={index()} />}
      </For>
      <h2>Edit scores</h2>
      <For each={state.players}>
        {(player) => (
          <div>
            {player.name}
            <input
              aria-label={`${player.name} score`}
              type="number"
              value={player.score}
              onInput={(event) => {
                const score = event.currentTarget.valueAsNumber;
                if (Number.isFinite(score))
                  setState((draft) => {
                    draft.players.find(
                      (item) => item.name === player.name,
                    ).score = score;
                  });
              }}
            />
            <button
              onClick={() =>
                setState((draft) => {
                  draft.players.splice(
                    draft.players.findIndex(
                      (item) => item.name === player.name,
                    ),
                    1,
                  );
                })
              }
            >
              Remove {player.name}
            </button>
          </div>
        )}
      </For>
      <input placeholder="New player..." ref={newName} />
      <input aria-label="New score" type="number" ref={newScore} />
      <button
        onClick={() => {
          const name = newName.value.trim(),
            score = newScore.valueAsNumber;
          if (
            !name ||
            !Number.isFinite(score) ||
            state.players.some((player) => player.name === name)
          )
            return;
          setState((draft) => {
            draft.players.push({ name, score });
          });
          newName.value = newScore.value = '';
        }}
      >
        Add
      </button>
      <style>{`.player { padding: 8px; height: 40px; box-sizing: border-box; } input { margin: 4px; }`}</style>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
